  if(node.type==='paragraph')return children.join('');
  if(node.type==='heading')return`${'#'.repeat(Math.max(1,Math.min(3,node.attrs?.level||1)))} ${children.join('')}`;
  if(node.type==='bulletList')return(node.content||[]).map((item:any)=>`- ${markdownFromNode(item).replace(/\n/g,'\n  ')}`).join('\n');
  if(node.type==='orderedList')return(node.content||[]).map((item:any,index:number)=>`${(node.attrs?.start||1)+index}. ${markdownFromNode(item).replace(/\n/g,'\n   ')}`).join('\n');
  if(node.type==='taskList')return(node.content||[]).map((item:any)=>markdownFromNode(item)).join('\n');
  if(node.type==='taskItem')return`- [${node.attrs?.checked?'x':' '}] ${(node.content||[]).map((item:any)=>markdownFromNode(item)).join(' ')}`;
  if(node.type==='listItem')return children.join('\n');
  if(node.type==='blockquote')return children.join('\n').split('\n').map((line:string)=>`> ${line}`).join('\n');
  if(node.type==='codeBlock')return`\`\`\`${node.attrs?.language||''}\n${(node.content||[]).map((item:any)=>item.text||'').join('')}\n\`\`\``;
  if(node.type==='horizontalRule')return'---';
  if(node.type==='safeImageBlock')return`![${node.attrs?.alt||''}](${node.attrs?.src||''})`;
  if(node.type==='attachmentBlock')return`[${node.attrs?.filename||'첨부파일'}](/api/attachments/${node.attrs?.id||''})`;
  if(node.type==='table'){
    const rows=(node.content||[]).map((row:any)=>`| ${(row.content||[]).map((cell:any)=>(cell.content||[]).map(markdownFromNode).join(' ').replace(/\|/g,'\\|')).join(' | ')} |`);
    if(rows.length>1){const width=(node.content?.[0]?.content||[]).length;rows.splice(1,0,`| ${Array(width).fill('---').join(' | ')} |`);}return rows.join('\n');
  }
  if(['tableRow','tableCell','tableHeader'].includes(node.type))return children.join(' ');
