    const image=line.match(/^!\[([^\]]*)\]\((https:\/\/[^\s)]+|\/(?!\/)[^\s)]*)\)$/);if(image){const src=safeImageSource(image[2]);if(src)content.push({type:'safeImageBlock',attrs:{src,alt:image[1].slice(0,200)}});index++;continue;}
