  async function saveProperties(properties:DatabaseProperty[]){if(!database)return;await api(`/databases/${database.id}/properties`,{method:'PATCH',body:JSON.stringify({properties})});setDatabase({...database,properties});notify('사용자 정의 속성을 저장했습니다.');}
