  function applySavedView(view:SavedDatabaseView){if(!database)return;setActiveViewId(view.id);setDatabase({...database,view_type:view.view_type});setFilter(view.status_filter);setPriorityFilter(view.priority_filter||'all');setDateFilter(view.due_filter||'all');setQuery(view.search_query||'');setSortBy(view.sort_by_field||view.sort_by);setSortBy2(view.sort_by_2||'none');const savedGroup=view.group_by_field||view.group_by||'none';setGroupBy(savedGroup.startsWith('custom:')&&!database.properties?.some(property=>savedGroup===`custom:${property.id}`)?'none':savedGroup);setRowPeekMode(view.row_open_mode||'side');try{setVisibleProperties(JSON.parse(view.visible_properties_json||'[]'));}catch{setVisibleProperties([]);}}
