      const titleCol=hasHeader?titleIndex:0,statusCol=index(['상태','status'],1),assigneeCol=index(['담당자','assignee','owner'],2),dueCol=index(['기한','마감일','duedate','deadline'],3),priorityCol=index(['우선순위','priority'],4),descriptionCol=index(['설명','내용','description'],5);
